param([Parameter(Mandatory)][string]$OutputPath)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}
$texts=[Collections.Generic.List[object]]::new();$texts.Add([int[]]@());$level=[Collections.Generic.List[object]]::new();$level.Add([int[]]@());foreach($length in 1..4){$next=[Collections.Generic.List[object]]::new();foreach($prefix in $level){foreach($unit in @(65,0xd800,0xdc00)){$v=[int[]](@($prefix)+@($unit));$texts.Add($v);$next.Add($v)}};$level=$next.ToArray()};foreach($v in @(@(0),@(0x7ff),@(0x800),@(0xd7ff),@(0xe000),@(0xffff),@(0xdbff,0xdfff),@(65,0,0xdbff,0xdfff),@(0xd800,0xdbff,0xdfff,0xdc00))){$texts.Add([int[]]$v)}
$configs=@();foreach($emit in @($false,$true)){foreach($strict in @($false,$true)){$configs+=@([ordered]@{emit=$emit;strict=$strict;replacement=$null})}};foreach($replacement in @(@(),@(65,66),@(0xd800,0xdc00))){$configs+=@([ordered]@{emit=$false;strict=$false;replacement=[int[]]$replacement})}
$profiles=@();foreach($config in $configs){$encoding=[Text.Encoding]([Text.UTF8Encoding]::new([bool]$config.emit,[bool]$config.strict)).Clone();if($null -ne $config.replacement){$encoding.EncoderFallback=[Text.EncoderReplacementFallback]::new([string]::new([char[]][int[]]$config.replacement))};$rows=[Collections.Generic.List[object]]::new()
 foreach($sourceId in 0..($texts.Count-1)){$text=[char[]][int[]]$texts[$sourceId];foreach($split in 0..$text.Length){foreach($flushSecond in @($false,$true)){
  $encoder=$encoding.GetEncoder();$steps=@();foreach($block in 0..2){if($block -eq 0){$units=[char[]]::new($split);[Array]::Copy($text,0,$units,0,$split);$flush=$false}elseif($block -eq 1){$units=[char[]]::new($text.Length-$split);[Array]::Copy($text,$split,$units,0,$units.Length);$flush=$flushSecond}else{$units=[char[]]@();$flush=$true}
   foreach($operation in @('Count','Bytes')){$destination=$null;try{if($operation -eq 'Count'){$n=$encoder.GetByteCount($units,0,$units.Length,$flush)}else{$destination=[byte[]]::new(24);[Array]::Fill[byte]($destination,99);$n=$encoder.GetBytes($units,0,$units.Length,$destination,1,$flush)};$result=[ordered]@{ok=$true;count=$n}}catch{$e=$_.Exception;while(($e -is [Management.Automation.RuntimeException] -or $e -is [Reflection.TargetInvocationException]) -and $null -ne $e.InnerException){$e=$e.InnerException};$result=[ordered]@{ok=$false;exception=$e.GetType().FullName;hResult=$e.HResult;paramName=$(if($e -is [ArgumentException]){$e.ParamName}else{$null})};if($e -is [Text.EncoderFallbackException]){$result.unknown=[int]$e.CharUnknown;$result.index=$e.Index}}
    $steps+=@([ordered]@{operation=$operation;block=$block;flush=$flush;result=$result;after=$(if($null -eq $destination){$null}else{,[int[]]$destination})})
   }
  };$rows.Add([ordered]@{sourceId=$sourceId;split=$split;flushSecond=$flushSecond;steps=$steps})
 }}}
 $probe=$encoding.GetEncoder();$profiles+=@([ordered]@{config=$config;freshInstances=-not [object]::ReferenceEquals($probe,$encoding.GetEncoder());fallbackSharedWithEncoding=[object]::ReferenceEquals($probe.Fallback,$encoding.EncoderFallback);rows=$rows.ToArray()})
}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();textInputs=$texts.ToArray();profiles=$profiles;qualification='SELECTED_STATEFUL_UTF8_ENCODER_ARRAY_PARTITIONS_ONLY; CAPACITY_CUSTOM_BUFFERS_CONVERT_SPAN_POINTER_METADATA_SOURCE_ABI_AND_TASK_ACCEPTANCE_OPEN'}
[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 14)+"`n",[Text.UTF8Encoding]::new($false));Write-Output 'PASS pinned stateful UTF-8 encoder partition capture'
